/*
 * test_inflate.c -- internal differential unit test for s2_inflate.c.
 * Not shipped.  Reads a vector file (generated by test_stage2.sh with
 * python3 + zlib, i.e. a second, independent implementation) where each line
 * is
 *
 *     <in_hex> <dict_hex|-> <out_hex|!>
 *
 * and "!" means "this stream must be refused".  Every vector is tried for
 * real; the exit status is non-zero if any check fails.
 */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "s2_inflate.h"

#define MAXBUF 262144

static unsigned char in[MAXBUF], dict[MAXBUF], out[MAXBUF], want[MAXBUF];
static int fails;

static int unhex(const char *s, unsigned char *buf, size_t cap, size_t *len)
{
    size_t n = 0;

    while (s[0] && s[1] && s[0] != ' ' && s[0] != '\n') {
        int hi, lo;
        char c;
        c = s[0];
        hi = (c >= '0' && c <= '9') ? c - '0'
           : (c >= 'a' && c <= 'f') ? c - 'a' + 10 : -1;
        c = s[1];
        lo = (c >= '0' && c <= '9') ? c - '0'
           : (c >= 'a' && c <= 'f') ? c - 'a' + 10 : -1;
        if (hi < 0 || lo < 0 || n >= cap)
            return -1;
        buf[n++] = (unsigned char)((hi << 4) | lo);
        s += 2;
    }
    *len = n;
    return 0;
}

int main(int argc, char **argv)
{
    FILE *f;
    char line[4 * MAXBUF + 16];
    int n = 0;

    if (argc != 2) {
        fprintf(stderr, "usage: test_inflate <vector-file>\n");
        return 2;
    }
    f = fopen(argv[1], "r");
    if (f == NULL) {
        perror("vector file");
        return 2;
    }
    printf("== s2_inflate differential unit tests (C vs python zlib) ==\n");
    while (fgets(line, (int)sizeof line, f) != NULL) {
        char *p = line, *e;
        size_t in_len = 0, dict_len = 0, want_len = 0, got;
        int expect_fail = 0;

        if (line[0] == '#' || line[0] == '\n')
            continue;
        e = strchr(p, ' ');
        if (e == NULL)
            continue;
        *e = '\0';
        if (unhex(p, in, sizeof in, &in_len) != 0) {
            printf("[FAIL] vector %d: bad in hex\n", n);
            fails++;
            continue;
        }
        p = e + 1;
        e = strchr(p, ' ');
        if (e == NULL)
            continue;
        *e = '\0';
        if (strcmp(p, "-") != 0 && unhex(p, dict, sizeof dict, &dict_len) != 0) {
            printf("[FAIL] vector %d: bad dict hex\n", n);
            fails++;
            continue;
        }
        p = e + 1;
        while (*p == '\n' || *p == '\r')
            *p = '\0';
        if (p[0] == '!') {
            expect_fail = 1;
        } else if (unhex(p, want, sizeof want, &want_len) != 0) {
            printf("[FAIL] vector %d: bad out hex\n", n);
            fails++;
            continue;
        }

        got = s2_inflate(in, in_len, dict_len ? dict : NULL, dict_len,
                         out, sizeof out);
        if (expect_fail) {
            if (got == (size_t)-1)
                ;
            else {
                printf("[FAIL] vector %d: accepted a stream that must be refused\n", n);
                fails++;
            }
        } else if (got == (size_t)-1) {
            printf("[FAIL] vector %d: refused in=%zu dict=%zu\n", n, in_len, dict_len);
            fails++;
        } else if (got != want_len || memcmp(out, want, want_len) != 0) {
            printf("[FAIL] vector %d: out=%zu bytes, wanted %zu\n", n, got, want_len);
            fails++;
        }
        n++;
    }
    fclose(f);
    printf("== %d vectors run, %d failed ==\n", n, fails);
    if (fails == 0) {
        printf("ALL TESTS PASSED\n");
        return 0;
    }
    printf("FAILURES PRESENT\n");
    return 1;
}